module Inner;
    typedef bit bit_q_t[$];
    byte unsigned p[$], back[$];
    bit b[$];
    initial begin
        p = '{8'hc7, 8'h3f};
        b = {<< 8 {bit_q_t'({<< {p}})}};
        $display("size=%0d b[0..3]=%b%b%b%b b[15]=%b", b.size(), b[0], b[1], b[2], b[3], b[15]);
        back = {<< 8 {bit_q_t'({<< {b}})}};
        $display("back size=%0d eq=%0d", back.size(), back == p);
    end
endmodule
module Top;
    Inner inner();
endmodule
